        {
            "name": "PYTHON: SEGMENT",
            "actions": [
                {
                    "name": "Create Marker Based on Segment Duration",
                    "isVisible": scope_segment,
                    "execute": create_marker
                },
                {
                    "name": "Create Segment Marker Based on Segment Duration",
                    "isVisible": scope_segment,
                    "execute": create_seg_marker
                },
            ]
